#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define N 10
static int parent[N];
static int rank_[N];

static void dsu_init(void) {
    for (int i = 0; i < N; ++i) {
        parent[i] = i;
        rank_[i] = 0;
    }
}

static int dsu_find(int x) {
    if (parent[x] != x)
        parent[x] = dsu_find(parent[x]);
    return parent[x];
}

static void dsu_union(int x, int y) {
    int rx = dsu_find(x);
    int ry = dsu_find(y);
    if (rx == ry) return;
    if (rank_[rx] < rank_[ry]) {
        parent[rx] = ry;
    } else if (rank_[rx] > rank_[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rank_[rx]++;
    }
}

static bool valid_index(long v) {
    return v >= 0 && v < N;
}

static void invalid(void) {
    puts("INVALID");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    dsu_init();
    int pos = 1;
    while (pos < argc) {
        const char *cmd = argv[pos++];
        if (strcmp(cmd, "U") == 0) {
            if (pos + 1 >= argc) { invalid(); break; }
            long a = strtol(argv[pos++], NULL, 10);
            long b = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) { invalid(); break; }
            dsu_union((int)a, (int)b);
            printf("UNION %ld %ld\n", a, b);
        } else if (strcmp(cmd, "F") == 0) {
            if (pos >= argc) { invalid(); break; }
            long a = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a)) { invalid(); break; }
            int rep = dsu_find((int)a);
            printf("FIND %ld=%d\n", a, rep);
        } else if (strcmp(cmd, "C") == 0) {
            if (pos + 1 >= argc) { invalid(); break; }
            long a = strtol(argv[pos++], NULL, 10);
            long b = strtol(argv[pos++], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) { invalid(); break; }
            puts(dsu_find((int)a) == dsu_find((int)b) ? "YES" : "NO");
        } else {
            invalid();
            break;
        }
    }
    return 0;
}
